// Native ResetValues clears the rogue value but retains its absolute timer.
void resetValues()
{
	const auto actor = actor_;
	const auto frame = frame_;
	const auto time = lastTime_;
	const auto deadline = nextRogueAt_;
	reset();
	actor_ = actor;
	frame_ = frame;
	lastTime_ = time;
	nextRogueAt_ = deadline;
	rogueKnown_ = deadline > 0.0f;
}

void followingStopped(float now)

if (actor_ == input.actor && frame_.mapGeneration == input.frame.mapGeneration)
	resetValues();
else
	reset();
actor_ = input.actor;

// Only states which consume navigation completion may update here.
if (state_ != CompatibilityStateId::MoveTo && state_ != CompatibilityStateId::InvestigateNoise)
	return StateResult::NoOp;
navigationCompletedFrame_ = context.frame;

// Native path planning includes ladders. The public adapter discovers
// their topology only for an objective route crossing NAV areas.
if (services_->service_compatibilitySurface().configuration().mode == compat::RuntimeMode::Compatibility &&
	observation.hasObjectiveTarget)
{
	nav::NavQuery query(navigation);
	nav::NavAreaMatch from{}, to{};
	const bool same = query.findContaining(observation.locomotion.position, kAreaVerticalTolerance, &from) == nav::NavQueryResult::Found &&
		query.findContaining(observation.objectiveTarget, kAreaVerticalTolerance, &to) == nav::NavQueryResult::Found && from.area == to.area;
	if (!same)
	{
		nav::NavLadderTopology topology{};
		(void)ladderTopology(&topology);
	}
}
